var CHAPTER_HEADING_RE = /^(chapter|book|part|section|prologue|epilogue|introduction|preface|foreword|afterword)\b/i;
var CHAPTER_MARK_RE = /^[ \t]*((?:chapter|book|part|section)\s+(?:the\s+)?(?:[ivxlcdm]+|\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|first|second|third|fourth|fifth)\b[^\n]{0,80}|(?:prologue|epilogue|introduction|preface|foreword|afterword)[^\n]{0,80}|(?:الفصل|الباب|الجزء|الكتاب)[^\n]{0,80})[ \t]*$/gim;

var CATALOG_INDEX = null;
var SEARCH_INDEX = null;
var SORT_CACHE = Object.create(null);
var BOOK_CACHE = Object.create(null);
var IN_FLIGHT = Object.create(null);

var VALID_SORTS = {
  popular: true,
  title: true,
  'title-desc': true,
  author: true,
  oldest: true,
  newest: true
};

var NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  hellip: '…', ndash: '–', mdash: '—', lsquo: '‘', rsquo: '’',
  ldquo: '“', rdquo: '”', laquo: '«', raquo: '»', middot: '·',
  bull: '•', copy: '©', reg: '®', trade: '™', rlm: '',
  aelig: 'æ', AElig: 'Æ', oelig: 'œ', OElig: 'Œ',
  aacute: 'á', Aacute: 'Á', eacute: 'é', Eacute: 'É',
  iacute: 'í', Iacute: 'Í', oacute: 'ó', Oacute: 'Ó',
  uacute: 'ú', Uacute: 'Ú', agrave: 'à', Agrave: 'À',
  egrave: 'è', Egrave: 'È', igrave: 'ì', Igrave: 'Ì',
  ograve: 'ò', Ograve: 'Ò', ugrave: 'ù', Ugrave: 'Ù',
  acirc: 'â', Acirc: 'Â', ecirc: 'ê', Ecirc: 'Ê',
  icirc: 'î', Icirc: 'Î', ocirc: 'ô', Ocirc: 'Ô',
  ucirc: 'û', Ucirc: 'Û', auml: 'ä', Auml: 'Ä',
  euml: 'ë', Euml: 'Ë', iuml: 'ï', Iuml: 'Ï',
  ouml: 'ö', Ouml: 'Ö', uuml: 'ü', Uuml: 'Ü',
  ccedil: 'ç', Ccedil: 'Ç', ntilde: 'ñ', Ntilde: 'Ñ',
  szlig: 'ß', eth: 'ð', ETH: 'Ð', thorn: 'þ',
  THORN: 'Þ', yacute: 'ý', Yacute: 'Ý', yuml: 'ÿ', Yuml: 'Ÿ'
};

function decodeEntities(str) {
  if (!str) return '';
  var s = String(str);
  return s.replace(/&(#x?[0-9a-f]+|[a-z][a-z0-9]*);/gi, function (m, name) {
    var cp = null;
    var low = name.toLowerCase();
    if (low.charAt(0) === '#') {
      var hex = low.charAt(1) === 'x';
      cp = parseInt(low.substring(hex ? 2 : 1), hex ? 16 : 10);
    } else if (Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, low)) {
      cp = NAMED_ENTITIES[low].charCodeAt(0);
    } else {
      return m;
    }
    if (!cp || cp < 0 || cp > 0x10FFFF) return m;
    if (cp > 0xFFFF) {
      cp -= 0x10000;
      return String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
    }
    return String.fromCharCode(cp);
  });
}

function cleanText(html) {
  return decodeEntities(String(html || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

function headingTitle(inner, tocText) {
  var source = String(inner || '');
  var alt = '';
  var altRe = /<img\b[^>]*\balt="([^"]*)"[^>]*>/gi;
  var am;
  while ((am = altRe.exec(source)) !== null) {
    if (am[1] && am[1].trim()) alt = am[1].trim();
  }
  var cleaned = source
    .replace(/<span[^>]*class="[^"]*(?:pagenum|caption)[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '')
    .replace(/<[^>]+>/g, ' ');
  var title = cleanText(cleaned);
  if (!title || /^\{?[ivxlcdm\d]+\}?\.?$/i.test(title)) {
    title = cleanText(tocText || alt);
  }
  var marker = title.search(/\b(?:chapter|book|part|section)\s+(?:the\s+)?(?:[ivxlcdm]+|\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|first|second|third|fourth|fifth)\b/i);
  if (marker > 0) title = title.substring(marker).trim();
  return title;
}

function normalizeAuthor(raw) {
  var s = String(raw || '').split(';')[0].trim();
  if (!s) return '';
  var parts = s.split(',');
  var clean = [];
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i].trim();
    if (p) clean.push(p);
  }
  if (clean.length < 2) return s;
  if (/^\d/.test(clean[1]) || /\b(?:BCE|CE|B\.C\.|A\.D\.|century|active|fl\.|d\.|ca\.)\b/i.test(clean[1])) {
    return clean[0];
  }
  return (clean[1] + ' ' + clean[0]).replace(/\s+/g, ' ').trim();
}

function coverUrl(id) {
  return 'https://www.gutenberg.org/cache/epub/' + id + '/pg' + id + '.cover.medium.jpg';
}

function canonicalUrl(id) {
  return 'https://www.gutenberg.org/ebooks/' + id;
}

function bookId(url) {
  var s = String(url || '');
  var m = s.match(/\/ebooks\/(\d+)/) || s.match(/\/cache\/epub\/(\d+)\//) || s.match(/^(\d+)$/);
  return m ? m[1] : '';
}

function pageNumber(page) {
  var n = parseInt(page, 10);
  return isNaN(n) || n < 1 ? 1 : Math.floor(n);
}

function xFetch(ctx, url) {
  try {
    return Promise.resolve(ctx.xFetch(url)).catch(function () { return null; });
  } catch (e) {
    return Promise.resolve(null);
  }
}

function catalogIndex() {
  if (CATALOG_INDEX) return CATALOG_INDEX;
  var map = Object.create(null);
  for (var i = 0; i < CATALOG.length; i++) {
    var row = CATALOG[i];
    map[String(row[0])] = {
      id: String(row[0]),
      title: row[1],
      author: row[2] || '',
      tags: row[3] || [],
      order: i
    };
  }
  CATALOG_INDEX = map;
  return map;
}

function searchIndex() {
  if (SEARCH_INDEX) return SEARCH_INDEX;
  var out = [];
  for (var i = 0; i < CATALOG.length; i++) {
    var row = CATALOG[i];
    out.push({
      entry: {
        id: String(row[0]),
        title: row[1],
        author: row[2] || '',
        tags: row[3] || [],
        order: i
      },
      title: String(row[1] || '').toLowerCase(),
      author: String(row[2] || '').toLowerCase(),
      hay: (String(row[1] || '') + ' ' + String(row[2] || '')).toLowerCase(),
      order: i
    });
  }
  SEARCH_INDEX = out;
  return out;
}

function tagLabels(tags) {
  var out = [];
  for (var i = 0; i < tags.length; i++) out.push(TAG_LABELS[tags[i]] || tags[i]);
  return out;
}

function toSummary(entry) {
  var labels = tagLabels(entry.tags);
  return {
    source: SOURCE_ID,
    url: canonicalUrl(entry.id),
    title: entry.title,
    author: entry.author || 'Project Gutenberg',
    coverUrl: coverUrl(entry.id),
    category: labels.length ? labels[0] : 'Classic Literature',
    tags: labels,
    status: 'مكتملة'
  };
}

function entryFromRow(row, order) {
  return {
    id: String(row[0]),
    title: row[1],
    author: row[2] || '',
    tags: row[3] || [],
    order: order
  };
}

function sortKey(order) {
  return order && VALID_SORTS[order] ? order : 'popular';
}

function compareText(a, b) {
  var x = String(a || '').toLowerCase();
  var y = String(b || '').toLowerCase();
  return x < y ? -1 : x > y ? 1 : 0;
}

function sortTitle(title) {
  var s = String(title || '').toLowerCase();
  s = s.replace(/^[\s"'“”‘’\[\](){}.,;:!?—–\-$]+/, '');
  s = s.replace(/^(the|a|an)\s+/, '');
  s = s.replace(/^[\s"'“”‘’\[\](){}.,;:!?—–\-$]+/, '');
  return s;
}

function sortedRows(order) {
  var key = sortKey(order);
  if (SORT_CACHE[key]) return SORT_CACHE[key];
  var rows = [];
  for (var i = 0; i < CATALOG.length; i++) rows.push({ row: CATALOG[i], order: i });
  if (key === 'title') {
    rows.sort(function (a, b) { return compareText(sortTitle(a.row[1]), sortTitle(b.row[1])) || a.order - b.order; });
  } else if (key === 'title-desc') {
    rows.sort(function (a, b) { return compareText(sortTitle(b.row[1]), sortTitle(a.row[1])) || a.order - b.order; });
  } else if (key === 'author') {
    rows.sort(function (a, b) {
      var aa = a.row[2] || '\uffff';
      var bb = b.row[2] || '\uffff';
      return compareText(aa, bb) || compareText(a.row[1], b.row[1]) || a.order - b.order;
    });
  } else if (key === 'oldest') {
    rows.sort(function (a, b) { return Number(a.row[0]) - Number(b.row[0]); });
  } else if (key === 'newest') {
    rows.sort(function (a, b) { return Number(b.row[0]) - Number(a.row[0]); });
  }
  SORT_CACHE[key] = rows;
  return rows;
}

function tagsFromText(text) {
  var out = [];
  var s = String(text || '');
  for (var i = 0; i < TAG_DEFS.length; i++) {
    if (TAG_DEFS[i][1].test(s)) out.push(TAG_DEFS[i][0]);
  }
  return out;
}

function removeBalancedDiv(html, id) {
  var s = String(html || '');
  var openRe = new RegExp('<div[^>]*\\bid="' + id + '"[^>]*>', 'i');
  var open = openRe.exec(s);
  if (!open) return s;
  var start = open.index;
  var tagRe = /<\/?div\b[^>]*>/gi;
  tagRe.lastIndex = start + open[0].length;
  var depth = 1;
  var m;
  while ((m = tagRe.exec(s)) !== null) {
    depth += m[0].charAt(1) === '/' ? -1 : 1;
    if (depth === 0) return s.substring(0, start) + s.substring(m.index + m[0].length);
  }
  return s;
}

function removeBlock(html, tag) {
  var s = String(html || '');
  var openRe = new RegExp('<' + tag + '\\b[^>]*>', 'i');
  var open = openRe.exec(s);
  if (!open) return s;
  var start = open.index;
  var tagRe = new RegExp('</?' + tag + '\\b[^>]*>', 'gi');
  tagRe.lastIndex = start + open[0].length;
  var depth = 1;
  var m;
  while ((m = tagRe.exec(s)) !== null) {
    depth += m[0].charAt(1) === '/' ? -1 : 1;
    if (depth === 0) return s.substring(0, start) + s.substring(m.index + m[0].length);
  }
  return s;
}

function cleanHtmlSlice(html) {
  var s = String(html || '');
  s = removeBalancedDiv(s, 'pg-footer');
  s = removeBalancedDiv(s, 'pg-header');
  s = removeBlock(s, 'footer');
  s = removeBlock(s, 'header');
  s = s.replace(/<script[\s\S]*?<\/script>/gi, '');
  s = s.replace(/<style[\s\S]*?<\/style>/gi, '');
  s = s.replace(/<span[^>]*class="[^"]*pagenum[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '');
  s = s.replace(/<span[^>]*class="[^"]*(?:letra|firstletter|dropcap|drop-cap|initial)[^"]*"[^>]*>([\s\S]*?)<\/span>/gi, function (m, inner) {
    var alt = inner.match(/<img[^>]*\balt="([^"]*)"/i);
    return alt && alt[1] ? alt[1] : cleanText(inner);
  });
  s = s.replace(/<img\b[^>]*\balt="([A-Za-z])"[^>]*>/gi, '$1');
  s = s.replace(/<table[\s\S]*?<\/table>/gi, '');
  s = s.replace(/<sup[^>]*>\s*\d+\s*<\/sup>/gi, '');
  s = s.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  var br = '\uE000';
  s = s.replace(/<br\s*\/?>/gi, br);
  s = s.replace(/<\/(p|div|h[1-6]|li|blockquote|tr)>/gi, '\n\n');
  s = s.replace(/<[^>]+>/g, '');
  s = decodeEntities(s);
  s = s.replace(/[ \t]+\n/g, '\n');

  var blocks = s.split(/\n{2,}/);
  var out = [];
  for (var i = 0; i < blocks.length; i++) {
    var block = blocks[i].replace(/\n/g, ' ').replace(/[ \t]{2,}/g, ' ').trim();
    if (block) out.push(block);
  }
  s = out.join('\n\n');
  s = s.split(br).join('\n');
  s = s.replace(/[ \t]*\n[ \t]*/g, '\n');
  return s.trim();
}

function cleanTextSlice(text) {
  var s = String(text || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  s = s.replace(/\[Illustration[^\]]*\]/gi, '');
  var parts = s.split(/\n\s*\n/);
  var out = [];
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i].replace(/\n/g, ' ').replace(/[ \t]{2,}/g, ' ').trim();
    if (p) out.push(p);
  }
  return out.join('\n\n');
}

function stripTextBoilerplate(raw) {
  var s = String(raw || '').replace(/\r\n/g, '\n');
  var start = s.search(/\*\*\* ?START OF (?:THE|THIS) PROJECT GUTENBERG EBOOK[^\n]*\*\*\*/i);
  if (start !== -1) {
    var nl = s.indexOf('\n', start);
    s = nl !== -1 ? s.substring(nl + 1) : '';
  }
  var end = s.search(/\*\*\* ?END OF (?:THE|THIS) PROJECT GUTENBERG EBOOK/i);
  if (end !== -1) s = s.substring(0, end);
  return s.trim();
}

function chaptersFromHtml(html, id) {
  var headings = [];
  var headingRe = /<h([1-6])\b([^>]*)>([\s\S]*?)<\/h\1>/gi;
  var m;
  while ((m = headingRe.exec(html)) !== null) {
    var attrs = m[2] || '';
    var inner = m[3] || '';
    var idMatch = attrs.match(/\bid="([^"]+)"/i);
    var anchor = idMatch ? idMatch[1] : '';
    if (!anchor) {
      var innerMatch = inner.match(/<a[^>]*\bid="([^"]+)"/i);
      if (innerMatch) anchor = innerMatch[1];
    }
    var title = headingTitle(inner, '');
    if (!anchor) continue;
    if (/^page_/i.test(anchor)) continue;
    if (title && META_HEADING_RE.test(title)) continue;
    headings.push({ anchor: anchor, title: title, inner: inner, start: m.index, end: m.index + m[0].length });
  }
  if (headings.length === 0) return [];

  var byAnchor = Object.create(null);
  for (var i = 0; i < headings.length; i++) {
    if (!byAnchor[headings[i].anchor]) byAnchor[headings[i].anchor] = headings[i];
  }

  var tocLinks = [];
  var seen = Object.create(null);
  var anchorRe = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
  while ((m = anchorRe.exec(html)) !== null) {
    if (!/\bclass="[^"]*\bpginternal\b/i.test(m[1])) continue;
    var hrefMatch = m[1].match(/\bhref="#([^"]+)"/i);
    if (!hrefMatch) continue;
    var tocId = hrefMatch[1];
    if (seen[tocId] || /^page_/i.test(tocId)) continue;
    if (!byAnchor[tocId]) continue;
    seen[tocId] = true;
    tocLinks.push({ id: tocId, text: cleanText(m[2]) });
  }

  var selected = [];
  if (tocLinks.length > 0) {
    for (var t = 0; t < tocLinks.length; t++) {
      selected.push({ heading: byAnchor[tocLinks[t].id], tocText: tocLinks[t].text });
    }
  } else {
    for (var h = 0; h < headings.length; h++) {
      if (CHAPTER_HEADING_RE.test(headings[h].title)) {
        selected.push({ heading: headings[h], tocText: '' });
      }
    }
    if (selected.length === 0 && headings.length >= 2) {
      for (var all = 0; all < headings.length; all++) {
        selected.push({ heading: headings[all], tocText: '' });
      }
    }
  }
  if (selected.length === 0) return [];

  selected.sort(function (a, b) { return a.heading.start - b.heading.start; });
  var items = [];
  var seenStart = Object.create(null);
  for (var s = 0; s < selected.length; s++) {
    var item = selected[s];
    if (seenStart[item.heading.start]) continue;
    seenStart[item.heading.start] = true;
    items.push(item);
  }

  var out = [];
  for (var c = 0; c < items.length; c++) {
    var current = items[c];
    var heading = current.heading;
    var next = items[c + 1];
    var end = next ? next.heading.start : html.length;
    var title = headingTitle(heading.inner, current.tocText);
    if (!title || META_HEADING_RE.test(title)) continue;
    var content = cleanHtmlSlice(html.substring(heading.end, end));
    if (content.length < 10) continue;
    out.push({
      anchor: heading.anchor,
      title: title,
      start: heading.start,
      contentStart: heading.end,
      end: end,
      number: out.length + 1,
      url: canonicalUrl(id) + '#' + heading.anchor
    });
  }
  return out;
}

function chaptersFromText(text, id) {
  var s = stripTextBoilerplate(text);
  var marks = [];
  var m;
  CHAPTER_MARK_RE.lastIndex = 0;
  while ((m = CHAPTER_MARK_RE.exec(s)) !== null) {
    marks.push({ title: m[1].trim(), start: m.index, len: m[0].length });
    if (m[0].length === 0) CHAPTER_MARK_RE.lastIndex++;
  }
  if (marks.length === 0) {
    return [{
      anchor: '',
      title: 'Full text',
      start: 0,
      contentStart: 0,
      end: s.length,
      number: 1,
      url: canonicalUrl(id)
    }];
  }
  var out = [];
  for (var i = 0; i < marks.length; i++) {
    var next = marks[i + 1];
    var contentStart = marks[i].start + marks[i].len;
    var end = next ? next.start : s.length;
    if (cleanTextSlice(s.substring(contentStart, end)).length < 10) continue;
    out.push({
      anchor: '',
      title: marks[i].title || 'Chapter ' + (out.length + 1),
      start: marks[i].start,
      contentStart: contentStart,
      end: end,
      number: out.length + 1,
      url: canonicalUrl(id) + '#pg-chapter-' + (out.length + 1)
    });
  }
  if (out.length === 0) {
    return [{
      anchor: '',
      title: 'Full text',
      start: 0,
      contentStart: 0,
      end: s.length,
      number: 1,
      url: canonicalUrl(id)
    }];
  }
  return out;
}

function chapterText(book, chapter) {
  var raw = book.raw.substring(chapter.contentStart, chapter.end);
  return book.kind === 'html' ? cleanHtmlSlice(raw) : cleanTextSlice(raw);
}

function wordCount(book) {
  var total = 0;
  for (var i = 0; i < book.chapters.length; i++) {
    var text = chapterText(book, book.chapters[i]);
    total += text.split(/\s+/).filter(Boolean).length;
  }
  return total;
}

function cacheBook(id, data) {
  BOOK_CACHE[id] = data;
  var keys = Object.keys(BOOK_CACHE);
  if (keys.length > BOOK_CACHE_CAP) {
    var oldest = keys[0];
    for (var i = 1; i < keys.length; i++) {
      if (BOOK_CACHE[keys[i]].ts < BOOK_CACHE[oldest].ts) oldest = keys[i];
    }
    delete BOOK_CACHE[oldest];
  }
}

async function loadBook(id, ctx) {
  var html = '';
  var urls = [
    'https://www.gutenberg.org/cache/epub/' + id + '/pg' + id + '-images.html',
    'https://www.gutenberg.org/cache/epub/' + id + '/pg' + id + '.html'
  ];
  for (var i = 0; i < urls.length; i++) {
    var res = await xFetch(ctx, urls[i]);
    if (res && res.ok && res.text && res.text.length > 200 && /<html/i.test(res.text)) {
      if (/(?:id="pg-header"|id="pg-footer"|class="pg-boilerplate")/i.test(res.text)) {
        html = res.text;
        break;
      }
    }
  }

  if (html) {
    var htmlChapters = chaptersFromHtml(html, id);
    if (htmlChapters.length > 0) {
      var htmlData = { kind: 'html', raw: html, chapters: htmlChapters, ts: Date.now() };
      cacheBook(id, htmlData);
      return htmlData;
    }
  }

  var textRes = await xFetch(ctx, 'https://www.gutenberg.org/cache/epub/' + id + '/pg' + id + '.txt');
  if (!textRes || !textRes.ok || !textRes.text) {
    throw new Error('فشل جلب الكتاب من Project Gutenberg');
  }
  var strippedText = stripTextBoilerplate(textRes.text);
  var textData = {
    kind: 'text',
    raw: strippedText,
    chapters: chaptersFromText(strippedText, id),
    ts: Date.now()
  };
  cacheBook(id, textData);
  return textData;
}

function fetchBook(id, ctx) {
  var cached = BOOK_CACHE[id];
  if (cached && (Date.now() - cached.ts) < BOOK_CACHE_TTL) return Promise.resolve(cached);
  if (IN_FLIGHT[id]) return IN_FLIGHT[id];
  var p = loadBook(id, ctx);
  IN_FLIGHT[id] = p;
  p.then(function () { delete IN_FLIGHT[id]; }, function () { delete IN_FLIGHT[id]; });
  return p;
}

function tdValue(html, label) {
  var re = new RegExp('<th[^>]*>\\s*' + label + '\\s*</th>\\s*<td[^>]*>([\\s\\S]*?)</td>', 'i');
  var m = String(html || '').match(re);
  return m ? cleanText(m[1]) : '';
}

function tdValues(html, label) {
  var re = new RegExp('<th[^>]*>\\s*' + label + '\\s*</th>\\s*<td[^>]*>([\\s\\S]*?)</td>', 'gi');
  var out = [];
  var m;
  while ((m = re.exec(String(html || ''))) !== null) {
    var v = cleanText(m[1]);
    if (v) out.push(v);
  }
  return out;
}

function metaFromPage(html, id) {
  var title = tdValue(html, 'Title');
  var author = normalizeAuthor(tdValue(html, 'Author'));
  var h1 = String(html || '').match(/<h1[^>]*id="book_title"[^>]*>([\s\S]*?)<\/h1>/i);
  if (!title && h1) {
    var h1Text = cleanText(h1[1]);
    var byIdx = h1Text.lastIndexOf(' by ');
    title = byIdx !== -1 ? h1Text.substring(0, byIdx).trim() : h1Text;
    if (!author && byIdx !== -1) author = h1Text.substring(byIdx + 4).trim();
  }
  if (!title) {
    var titleTag = String(html || '').match(/<title>([\s\S]*?)<\/title>/i);
    if (titleTag) {
      var t = cleanText(titleTag[1]);
      var by = t.lastIndexOf(' by ');
      title = by !== -1 ? t.substring(0, by).trim() : t;
      if (!author && by !== -1) author = t.substring(by + 4).trim();
    }
  }

  var cover = '';
  var imgRe = /<img\b[^>]*>/gi;
  var img;
  while ((img = imgRe.exec(String(html || ''))) !== null) {
    if (!/\bclass="[^"]*cover-art\b/i.test(img[0])) continue;
    var src = img[0].match(/\bsrc="([^"]+)"/i);
    if (src) {
      cover = src[1];
      break;
    }
  }

  var subjects = tdValues(html, 'Subject');
  var description = '';
  var metaRe = /<meta\b[^>]*>/gi;
  var meta;
  while ((meta = metaRe.exec(String(html || ''))) !== null) {
    if (!/\bname="description"/i.test(meta[0])) continue;
    var content = meta[0].match(/\bcontent="([^"]*)"/i);
    if (content) {
      description = cleanText(content[1]);
      break;
    }
  }

  var tags = tagsFromText(subjects.join(' ') + ' ' + description);
  var labels = tagLabels(tags);
  var summary = subjects.length
    ? 'Project Gutenberg public-domain edition. Subjects: ' + subjects.join('; ') + '.'
    : (description || 'Project Gutenberg public-domain edition.');

  return {
    title: title || ('Project Gutenberg #' + id),
    author: author || 'Project Gutenberg',
    coverUrl: cover || coverUrl(id),
    summary: summary,
    category: labels.length ? labels[0] : 'Classic Literature',
    tags: labels
  };
}

function metaFromBook(book, id) {
  var title = '';
  var author = 'Project Gutenberg';
  if (book && book.kind === 'html') {
    var h1 = String(book.raw).match(/<h1[^>]*id="book_title"[^>]*>([\s\S]*?)<\/h1>/i);
    if (h1) {
      var text = cleanText(h1[1]);
      var by = text.lastIndexOf(' by ');
      title = by !== -1 ? text.substring(0, by).trim() : text;
      if (by !== -1) author = text.substring(by + 4).trim();
    }
  }
  if (!title && book && book.kind === 'text') {
    var lines = String(book.raw).replace(/\r\n/g, '\n').split('\n');
    for (var i = 0; i < lines.length; i++) {
      if (lines[i].trim()) {
        title = lines[i].trim();
        break;
      }
    }
  }
  return {
    title: title || ('Project Gutenberg #' + id),
    author: author,
    coverUrl: coverUrl(id),
    summary: 'Project Gutenberg public-domain edition.',
    category: 'Classic Literature',
    tags: []
  };
}

registerExtension({
  id: 'site:gutenberg',
  name: 'Project Gutenberg',
  lang: 'en',
  version: '1.0.1',
  apiVersion: 1,
  baseUrl: 'https://www.gutenberg.org',

  _catalogEntry: function (id) {
    return catalogIndex()[String(id)] || null;
  },

  _entryInfo: function (entry) {
    var labels = tagLabels(entry.tags);
    return {
      title: entry.title,
      author: entry.author || 'Project Gutenberg',
      coverUrl: coverUrl(entry.id),
      summary: 'Project Gutenberg public-domain edition.' +
        (labels.length ? ' Themes: ' + labels.join(', ') + '.' : ''),
      category: labels.length ? labels[0] : 'Classic Literature',
      tags: labels
    };
  },

  _assembleInfo: function (meta, id, totalChapters, words) {
    return {
      source: this.id,
      url: canonicalUrl(id),
      title: meta.title || ('Project Gutenberg #' + id),
      author: meta.author || 'Project Gutenberg',
      coverUrl: meta.coverUrl || coverUrl(id),
      summary: meta.summary || 'Project Gutenberg public-domain edition.',
      status: 'مكتملة',
      category: meta.category || 'Classic Literature',
      tags: meta.tags || [],
      totalChapters: totalChapters || 1,
      wordCount: words > 0 ? words : undefined,
      readingMinutes: words > 0 ? Math.max(1, Math.round(words / 140)) : undefined
    };
  },

  parseNovelInfo: async function (url, ctx) {
    var id = bookId(url);
    if (!id) throw new Error('رابط كتاب غير صالح');

    var entry = this._catalogEntry(id);
    var book = null;
    var meta = entry ? this._entryInfo(entry) : null;

    if (entry) {
      book = await fetchBook(id, ctx).catch(function () { return null; });
    } else {
      var results = await Promise.all([
        xFetch(ctx, canonicalUrl(id)),
        fetchBook(id, ctx).catch(function () { return null; })
      ]);
      var page = results[0];
      book = results[1];
      if (page && page.ok && page.text) meta = metaFromPage(page.text, id);
      if (!meta) meta = metaFromBook(book, id);
    }

    var chapters = book ? book.chapters : [];
    var words = book ? wordCount(book) : 0;
    return this._assembleInfo(meta, id, chapters.length, words);
  },

  parseChapterList: async function (novelUrl, ctx) {
    var id = bookId(novelUrl);
    if (!id) throw new Error('رابط كتاب غير صالح');
    var book = await fetchBook(id, ctx);
    var out = [];
    for (var i = 0; i < book.chapters.length; i++) {
      var c = book.chapters[i];
      out.push({ url: c.url, number: c.number, title: c.title });
    }
    return out;
  },

  parseChapterContent: async function (chapterUrl, ctx) {
    var id = bookId(chapterUrl);
    if (!id) throw new Error('رابط فصل غير صالح');
    var hash = '';
    var raw = String(chapterUrl || '');
    var hashIdx = raw.indexOf('#');
    if (hashIdx !== -1) hash = raw.substring(hashIdx + 1);
    try { hash = decodeURIComponent(hash); } catch (e) {}

    var book = await fetchBook(id, ctx);
    var chapter = null;
    var i;
    if (hash.indexOf('pg-chapter-') === 0) {
      var n = parseInt(hash.substring(11), 10);
      if (n >= 1 && n <= book.chapters.length) chapter = book.chapters[n - 1];
    }
    if (!chapter && hash) {
      for (i = 0; i < book.chapters.length; i++) {
        if (book.chapters[i].anchor === hash) {
          chapter = book.chapters[i];
          break;
        }
      }
    }
    if (!chapter) chapter = book.chapters[0];
    if (!chapter) throw new Error('لم يتم العثور على الفصل');
    return chapterText(book, chapter);
  },

  searchNovels: async function (query, page, ctx) {
    var q = String(query || '').trim().toLowerCase();
    if (!q) return this.getPopularNovels(page, ctx);

    var tokens = q.split(/\s+/);
    var index = searchIndex();
    var hits = [];
    for (var i = 0; i < index.length; i++) {
      var item = index[i];
      var all = true;
      for (var t = 0; t < tokens.length; t++) {
        if (item.hay.indexOf(tokens[t]) === -1) {
          all = false;
          break;
        }
      }
      if (!all) continue;

      var score = 10;
      if (item.title === q) score = 100;
      else if (item.title.indexOf(q) === 0) score = 80;
      else if (item.title.indexOf(q) !== -1) score = 60;
      else if (item.author.indexOf(q) === 0) score = 40;
      else if (item.author.indexOf(q) !== -1) score = 30;
      hits.push({ entry: item.entry, score: score, order: item.order });
    }

    hits.sort(function (a, b) {
      return b.score - a.score || a.order - b.order;
    });

    var pageNum = pageNumber(page);
    var start = (pageNum - 1) * PAGE_SIZE;
    var out = [];
    for (var h = start; h < hits.length && h < start + PAGE_SIZE; h++) {
      out.push(toSummary(hits[h].entry));
    }
    return out;
  },

  getPopularNovels: async function (page, sort, ctx) {
    if (sort && typeof sort.xFetch === 'function') { ctx = sort; sort = ''; }
    var order = sortKey(typeof sort === 'string' ? sort : '');
    var rows = sortedRows(order);
    var pageNum = pageNumber(page);
    var start = (pageNum - 1) * PAGE_SIZE;
    var out = [];
    for (var i = start; i < rows.length && i < start + PAGE_SIZE; i++) {
      out.push(toSummary(entryFromRow(rows[i].row, rows[i].order)));
    }
    return out;
  },

  getSortOptions: async function () {
    return [
      { name: 'الأكثر شعبية', slug: 'popular' },
      { name: 'A-Z', slug: 'title' },
      { name: 'Z-A', slug: 'title-desc' },
      { name: 'المؤلف A-Z', slug: 'author' },
      { name: 'الأقدم', slug: 'oldest' },
      { name: 'الأحدث', slug: 'newest' }
    ];
  },

  getCategories: async function () {
    return [
      { name: 'Fiction', slug: 'fiction' },
      { name: 'Poetry', slug: 'poetry' },
      { name: 'Drama', slug: 'drama' },
      { name: 'Adventure', slug: 'adventure' },
      { name: 'Mystery', slug: 'mystery' },
      { name: 'Romance', slug: 'romance' },
      { name: 'Fantasy', slug: 'fantasy' },
      { name: 'Horror', slug: 'horror' },
      { name: 'Short Stories', slug: 'short-stories' },
      { name: 'Fairy Tales', slug: 'fairy-tales' },
      { name: 'Folklore', slug: 'folklore' },
      { name: 'Philosophy', slug: 'philosophy' },
      { name: 'History', slug: 'history' }
    ];
  },

  getCategoryNovels: async function (categorySlug, page, sort, ctx) {
    if (sort && typeof sort.xFetch === 'function') { ctx = sort; sort = ''; }
    var slug = String(categorySlug || '').trim();
    if (!slug || slug === 'all') return this.getPopularNovels(page, sort, ctx);

    var order = sortKey(typeof sort === 'string' ? sort : '');
    var rows = sortedRows(order);
    var pageNum = pageNumber(page);
    var start = (pageNum - 1) * PAGE_SIZE;
    var seen = 0;
    var out = [];
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i].row;
      var tags = row[3] || [];
      var has = false;
      for (var t = 0; t < tags.length; t++) {
        if (tags[t] === slug) {
          has = true;
          break;
        }
      }
      if (!has) continue;
      if (seen >= start && seen < start + PAGE_SIZE) {
        out.push(toSummary(entryFromRow(row, rows[i].order)));
      }
      seen++;
    }
    return out;
  },

  fetchLatestChapters: async function () {
    return [];
  }
});
